mapper.select:
SELECT 'MEDIA' AS type, m.id, m.title AS text, l.name AS subtitle FROM media m LEFT JOIN location l ON l.id = m.location_id AND l.status = 1 WHERE m.status = 1 AND m.title IS NOT NULL AND m.title != ''
AND ( m.title LIKE CONCAT('%', #{keyword}, '%') OR m.description LIKE CONCAT('%', #{keyword}, '%') OR m.tags LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY m.favorite_count DESC, m.like_count DESC, m.view_count DESC, m.id DESC LIMIT #{limit}

SELECT m.id, m.title, m.location_id, l.name AS location_name, COALESCE(NULLIF(m.thumbnail_key, ''), m.object_key) AS thumbnail_key, m.shot_at, m.view_count, m.like_count, m.favorite_count FROM media m LEFT JOIN location l ON l.id = m.location_id WHERE m.status = 1 AND m.id != #{sourceId} AND ( m.location_id = #{locationId}
OR LOCATE( CONCAT('|', #{tag}, '|'), CONCAT('|', COALESCE(m.tags, ''), '|') ) > 0
) ORDER BY m.like_count DESC, m.view_count DESC, m.id DESC LIMIT #{limit}

